WITH unpacked AS (SELECT id, ship_to, attributes['gift'] AS gift, SIZE(FILTER(items, i -> i.qty >= 3)) AS bulk_lines, TRANSFORM(items, i -> i.product_id) AS product_ids FROM carts) SELECT id, gift, ROW_NUMBER() OVER (ORDER BY bulk_lines DESC, id ASC) row_seq, LAG(bulk_lines, 2) OVER (ORDER BY bulk_lines ASC, id ASC) prev_bulk_lines, LAG(bulk_lines, 1, 0) OVER (ORDER BY bulk_lines ASC, id ASC) prev_bulk_lines_2 FROM unpacked WHERE bulk_lines BETWEEN 1 AND 3;
